      "download.lede": "احصل على أحدث إصدار من المحرر وقم بتوجيهه إلى مشروع PVSnesLib أو SGDK. الشوكة مفتوحة المصدر. يتم نشر الإصدارات على جيثب.",
      "download.button": "قم بالتنزيل على إصدارات GitHub",
