      "faq.eyebrow": "الأسئلة الشائعة",
      "faq.title1": "قبلك",
      "faq.title2": "أدخل الخرطوشة.",
      "faq.lede": "إجابات قصيرة على الأسئلة التي يطرحها المنفذ الرجعي عادةً.",
      "faq.official.q": "هل هذا هو محرك Godot الرسمي؟",
      "faq.official.a": "لا، إن Godot Retro Engine عبارة عن شوكة مستقلة لـ Godot 4.7، وتركز على تطوير SNES وMega Drive. وهي ليست تابعة أو معتمدة من قبل مؤسسة جودو.",
      "faq.convert.q": "هل يمكنه تحويل أي لعبة SNES أو Mega Drive؟",
      "faq.convert.a": "لا. الترجمة الثنائية بين 65816 و68000 ليست عملية في الوقت الحقيقي. تستخدم الشوكة محولات على مستوى المصدر مصممة لكل لعبة؛ Sonic 2 وGothicvania هما التطبيقان المرجعيان.",
      "faq.roms.q": "هل يتم تضمين ROMs أو الأصول المحمية بحقوق الطبع والنشر؟",
      "faq.roms.a": "لا، المحرر وسلاسل الأدوات مفتوحة المصدر. أنت تقوم بتزويد مشروعك المصدري والأصول وأقراص القراءة فقط التي تم الحصول عليها بشكل قانوني. لا يتم تعديل الملفات الأصلية أبدًا من قبل المصدرين.",
      "faq.apps.q": "هل يقوم بالفعل ببناء تطبيقات Windows وmacOS؟",
      "faq.apps.a": "نعم. تم بناء Linux محليًا. يتم تجميع Windows بشكل متقاطع مع MinGW-w64. تم تصميم macOS باستخدام osxcross كتطبيق عالمي x86_64 + Arm64. أرشيفات الإصدار موجودة على GitHub.",
      "faq.audio.q": "هل الصوت دقيق؟",
      "faq.audio.a": "ليس دائما. يستخدم صوت SNES وYM2612 تنسيقات وحدة تحكم حقيقية وعينات أصلية حيثما كان ذلك متاحًا، ولكن تظل بعض الأظرف والتوقيت والنسخ تقريبية.",
      "footer.about": "شوكة Godot مستقلة ومتوفرة في المصدر لتطوير وحدة التحكم 16 بت والنقل والتحقق من صحتها.",
