      "feature.audio.title": "Конзолна аудио работна маса",
      "feature.audio.desc": "MIDI, модулът и семплираният звук стават SNESMOD/BRR или YM2612/PSG VGM. SFX могат да бъдат синтезирани, конвертирани и визуализирани, преди да достигнат ROM.",
