      "faq.official.q": "Това ли е официалният Godot Engine?",
      "faq.official.a": "Не. Godot Retro Engine е независимо разклонение на Godot 4.7, фокусирано върху разработката на SNES и Mega Drive. Той не е свързан с или одобрен от Godot Foundation.",
      "faq.convert.q": "Може ли да преобразува някоя SNES или Mega Drive игра?",
      "faq.convert.a": "Не. Двоичният превод между 65816 и 68000 не е практичен в реално време. Разклонението използва адаптери на ниво източник, изградени за всяка игра; Sonic 2 и Gothicvania са референтните реализации.",
      "faq.roms.q": "Включени ли са ROM или защитени с авторски права активи?",
      "faq.roms.a": "Не. Редакторът и инструменталните вериги са с отворен код. Вие предоставяте свой собствен законно получен изходен проект, активи и ROM. Оригиналните файлове никога не се променят от износителите.",
      "faq.apps.q": "Наистина ли създава приложения за Windows и macOS?",
      "faq.apps.a": "да Linux е изграден нативно. Windows е кръстосано компилиран с MinGW-w64. macOS е създаден с osxcross като универсално x86_64 + arm64 приложение. Архивите на изданията са в GitHub.",
      "faq.audio.q": "Аудиото битово точно ли е?",
      "faq.audio.a": "Не винаги. Аудиото на SNES и YM2612 използва реални конзолни формати и оригинални семпли, където са налични, но някои обвивки, синхронизация и транскрипции остават приблизителни.",
