      "footer.godot_license": "Godot লাইসেন্স",
      "footer.contributors": "অবদানকারী",
      "footer.copyright": "© 2026 Godot রেট্রো ইঞ্জিন অবদানকারী। Godot হল Juan Linietsky, Ariel Manzur এবং অবদানকারীদের ট্রেডমার্ক। এই স্বাধীন কাঁটা গোডট ফাউন্ডেশনের সাথে অনুমোদিত বা অনুমোদিত নয়।",
      "footer.note": "কোনো রম বান্ডিল করা হয়নি। আপনার নিজের আইনত প্রাপ্ত সম্পদ আনুন.",
      "feature.fidelity.desc": "ক্রস-প্ল্যাটফর্ম রপ্তানি আপনাকে সতর্ক করে যখন ম্যানুয়াল কাজের প্রয়োজন হয়, এবং জেনারেট করা প্রকল্পগুলির নাম দেওয়া হয় {{SNES}} / {{MD}} যাতে তারা কখনই উত্সের সাথে বিভ্রান্ত না হয়৷",
