      "footer.copyright": "© 2026 přispěvatelé Godot Retro Engine. Godot je ochranná známka Juana Linietského, Ariela Manzura a přispěvatelů. Tento nezávislý fork není přidružen ani schválen Godot Foundation.",
      "footer.note": "Žádné ROM přibalené. Přineste si vlastní legálně nabytý majetek.",
