      "footer.copyright": "© 2026 Godot Retro Engine kaastöötajad. Godot on Juan Linietsky, Ariel Manzuri ja kaastööliste kaubamärk. See sõltumatu kahvel ei ole Godoti sihtasutusega seotud ega selle poolt heaks kiidetud.",
      "footer.note": "Ühtegi ROM-i komplektis pole. Tooge oma seaduslikult saadud vara.",
      "feature.fidelity.desc": "Platvormideülene eksport hoiatab teid, kui on vaja käsitsi tööd teha, ja loodud projektid kannavad nime {{SNES}} / {{MD}}, et neid kunagi allikaga segi ei läheks.",
