      "features.lede": "این فورک گردش کار گودو را حفظ می کند و قطعاتی را که یک پروژه یکپارچهسازی با سیستمعامل واقعاً به آن نیاز دارد را اضافه می کند: زنجیره ابزار، مبدل های دارایی، پروفایل های ROM، بازخورد شبیه ساز و آداپتورهای پورت مخصوص بازی.",
      "feature.build.title": "ساخت بازی دو کنسولی",
      "feature.build.desc": "یک پروژه PVSnesLib/SGDK واقعی ایجاد کنید و یک رام قابل پخش از همان ویرایشگر بسازید. هدف، نقشه‌بردار، نمایه رام و اسپلش را انتخاب کنید، سپس چک‌سوم را تأیید کنید.",
      "feature.ports.title": "پورت های بازی در سطح منبع",
      "feature.ports.desc": "آداپتورهای اختصاصی به جای تفسیر باینری 68000 یا 65816 در زمان واقعی، منطق بازی را برای CPU دیگر بازسازی می کنند. Sonic 2 و Gothicvania به عنوان نمونه‌های کاری عرضه می‌شوند.",
      "feature.import.title": "واردات صحنه بومی",
      "feature.import.desc": "Sprite2D، AnimatedSprite2D، TileMapLayer، برخوردها، دوربین ها و رابط کاربری را از صحنه گودو به یک بازیگر قابل حمل و زمان اجرای صحنه برای هر دو کنسول بیاورید.",
      "feature.editors.title": "ویرایشگرهای یکپارچهسازی با سیستمعامل",
      "feature.editors.desc": "ویرایشگرهای استیج، اسپرایت، انیمیشن، پالت، برخورد، صدا، ورودی، گراف حالت و کد یک قالب پروژه و یک خط لوله ساخت را به اشتراک می گذارند.",
      "feature.audio.title": "میز کار صوتی کنسول",
      "feature.audio.desc": "MIDI، ماژول و صدای نمونه برداری شده به SNESMOD/BRR یا YM2612/PSG VGM تبدیل می شوند. SFX را می توان قبل از رسیدن به ROM سنتز، تبدیل و پیش نمایش کرد.",
      "feature.preview.title": "شبیه ساز در حلقه",
