      "ports.title2": "دومین ساخت بومی.",
      "ports.lede": "68000 3.58 مگاهرتز را نمی توان با 65816 در زمان واقعی تفسیر کرد و بالعکس. فورک برای هر بازی آداپتورهایی ارسال می‌کند که دارایی‌های اصلی را می‌خوانند و بازی را در برابر SDK هدف بازسازی می‌کنند.",
      "ports.gothic.desc": "یک هومبروی کامل PVSnesLib که برای SGDK بازسازی شده است: صفحات سطح اصلی، برخورد، فیزیک قهرمانان، مبارزه با شمشیر، سه نوع دشمن، هنر عنوان و موسیقی.",
      "ports.sonic.desc": "قانون EHZ 1 برای 65816 بازسازی شد: چیدمان قطعه اصلی، برخورد، حلقه‌ها، باد نیک‌ها، فنرها، مانیتورها، حلقه‌ها، پیچ چوب پنبه‌باز، دنبال‌کننده Tails و موسیقی مشتق‌شده از SMPS.",
      "ports.callout.title": "صادرات بین پلتفرمی یک نقطه شروع است، نه جادو.",
      "ports.callout.text": "ویرایشگر هشداری را نشان می دهد، تنظیمات دستی را می خواهد و نتیجه را به عنوان ایجاد می کند",
      "pipeline.eyebrow": "گردش کار",
      "pipeline.title1": "از صحنه به کارتریج",
      "pipeline.title2": "در سه حلقه",
      "pipeline.step1.title": "واردات و نویسنده",
      "pipeline.step1.desc": "یک پروژه PVSnesLib، WLA-DX یا SGDK را باز کنید یا یک صحنه گودو را وارد کنید. از ویرایشگرهای مرحله، اسپرایت، انیمیشن، پالت و برخورد برای شکل دادن به بازی استفاده کنید.",
      "pipeline.step2.title": "تولید و ساخت",
      "pipeline.step2.desc": "Game Build یک پروژه مستقل با دارایی های تبدیل شده می نویسد، نمایه ROM را انتخاب می کند، SDK واقعی را اجرا می کند و تصویر حاصل را تایید می کند.",
      "pipeline.step3.title": "اجرا و تأیید کنید",
      "pipeline.step3.desc": "رام در یک هسته شبیه ساز واقعی بوت می شود. دکمه‌ها را فشار دهید، فریم‌ها را بردارید، به عقب برگردید، جریان صوتی را بررسی کنید و آنچه را که پیش‌نمایش به شما نشان می‌دهد، اصلاح کنید.",
