      "faq.official.q": "آیا این موتور رسمی گودو است؟",
      "faq.official.a": "نه. Godot Retro Engine یک فورک مستقل از Godot 4.7 است که بر توسعه SNES و Mega Drive متمرکز شده است. این بنیاد به بنیاد گودو وابسته یا تایید نشده است.",
