      "faq.convert.a": "نه. ترجمه باینری بین 65816 و 68000 در زمان واقعی عملی نیست. چنگال از آداپتورهای سطح منبع ساخته شده در هر بازی استفاده می کند. Sonic 2 و Gothicvania پیاده سازی های مرجع هستند.",
      "faq.roms.q": "آیا رام ها یا دارایی های دارای حق چاپ شامل می شوند؟",
