      "download.eyebrow": "הורד",
      "download.title1": "תתחיל לבנות",
      "download.title2": "עבור חומרה של 16 סיביות.",
      "download.lede": "קח את בניית העורך העדכנית והפנה אותו לפרויקט PVSnesLib או SGDK שלך. המזלג הוא קוד פתוח; מהדורות מתפרסמות ב-GitHub.",
      "download.button": "הורד במהדורות GitHub",
      "download.tiny": "מבנה מתויג אחרון: 0.1.60 · מזלג Godot 4.7",
      "download.note": "אין חשבון, אין טלמטריה, אין ROM מצורפים. הביאו נכסים משלכם שהושגו כחוק.",
      "faq.eyebrow": "שאלות נפוצות",
      "faq.title1": "לפניך",
      "faq.title2": "הכנס את המחסנית.",
      "faq.lede": "תשובות קצרות לשאלות שנמל רטרו בדרך כלל מעלה.",
      "faq.official.q": "האם זה המנוע הרשמי של Godot?",
      "faq.official.a": "לא. Godot Retro Engine הוא מזלג עצמאי של Godot 4.7, המתמקד בפיתוח SNES ו-Mega Drive. הוא אינו מזוהה עם או מאושר על ידי קרן Godot.",
      "faq.convert.q": "האם זה יכול להמיר כל משחק SNES או Mega Drive?",
      "faq.convert.a": "לא. תרגום בינארי בין 65816 ל-68000 אינו מעשי בזמן אמת. המזלג משתמש במתאמים ברמת המקור שנבנו לכל משחק; Sonic 2 ו- Gothicvania הם יישומי הייחוס.",
      "faq.roms.q": "האם ROM או נכסים המוגנים בזכויות יוצרים כלולים?",
      "faq.roms.a": "לא. העורך ושרשרת הכלים הם קוד פתוח. אתה מספק פרויקט מקור משלך, נכסים ו-ROMs. הקבצים המקוריים לעולם אינם משתנים על ידי היצואנים.",
      "faq.apps.q": "האם זה באמת בונה יישומי Windows ו-macOS?",
      "faq.apps.a": "כן. לינוקס בנויה באופן מקורי. Windows מקופלט עם MinGW-w64. macOS בנוי עם osxcross כאפליקציה אוניברסלית x86_64 + arm64. ארכיוני ההפצה נמצאים ב-GitHub.",
      "faq.audio.q": "האם סיביות האודיו מדויקות?",
      "faq.audio.a": "לא תמיד. אודיו SNES ו-YM2612 משתמשות בפורמטים אמיתיים של קונסולות ודגימות מקוריות היכן שהן זמינות, אך חלק מהמעטפות, התזמון והתמלולים נשארים בקירוב.",
      "footer.about": "מזלג Godot עצמאי, זמין במקור לפיתוח קונסולת 16 סיביות, העברה ואימות.",
