      "hero.eyebrow": "Godot független villája 4.7",
      "hero.title1": "Építsd a konzolokhoz",
      "hero.title2": "ez nevelt fel.",
      "hero.lede": "A Godot Retro Engine egy ingyenes, nyílt forráskódú Godot fork SNES és Mega Drive játékok építéséhez, portolásához és érvényesítéséhez. Valódi SDK-k, valódi ROM-ok, valódi emulátorok – forrásszintű adapterekkel a bináris fordításnál többet érdemlő játékokhoz.",
      "hero.download": "Töltse le a legújabbat",
      "hero.explore": "Fedezze fel a villát",
      "hero.meta1": "Windows · Linux · macOS",
      "hero.meta2": "MIT-engedéllyel rendelkező villa",
      "hero.meta3": "Nincs telemetria",
      "stats.consoles": "célkonzolok",
      "stats.editors": "retro szerkesztők",
      "stats.builds": "asztali buildek",
      "stats.source": "forrás szintű munkafolyamatok",
      "features.eyebrow": "A villa jellemzői",
      "features.title1": "Egy szerkesztő. Két konzol.",
      "features.title2": "Nulla fekete doboz.",
      "features.lede": "A villa megtartja Godot munkafolyamatát, és hozzáadja azokat az alkatrészeket, amelyekre egy retro projektnek valóban szüksége van: szerszámláncokat, eszközátalakítókat, ROM-profilokat, emulátor-visszajelzéseket és játékspecifikus portadaptereket.",
      "feature.build.title": "Kétkonzolos játéképítés",
      "feature.build.desc": "Hozzon létre egy valódi PVSnesLib/SGDK projektet, és készítsen egy lejátszható ROM-ot ugyanabból a szerkesztőből. Válassza ki a célt, a leképezőt, a ROM-profilt és a splash-t, majd érvényesítse az ellenőrző összeget.",
      "feature.ports.title": "Forrás szintű játékportok",
      "feature.ports.desc": "A dedikált adapterek újraépítik a játék logikáját a másik CPU számára, ahelyett, hogy valós időben értelmeznék a 68000 vagy 65816 bináris fájlokat. A Sonic 2 és a Gothicvania hajó mint működő példa.",
      "feature.import.title": "Natív jelenet importálása",
      "feature.import.desc": "Hozd a Sprite2D-t, az AnimatedSprite2D-t, a TileMapLayert, az ütközéseket, a kamerákat és a felhasználói felületet egy Godot-jelenetből hordozható színészekké és színpadi futásidővé mindkét konzolon.",
      "feature.editors.title": "Retro szerkesztők",
      "feature.editors.desc": "A színpadi, sprite-, animációs-, paletta-, ütközési-, hang-, beviteli-, állapotgrafikon- és kódszerkesztők egy projektformátumon és egy összeállítási folyamaton osztoznak.",
      "feature.audio.title": "Konzol audio munkapad",
      "feature.audio.desc": "A MIDI, a modul és a mintavételezett hang SNESMOD/BRR vagy YM2612/PSG VGM lesz. Az SFX szintetizálható, konvertálható és megtekinthető, mielőtt elérné a ROM-ot.",
      "feature.preview.title": "Emulátor a hurokban",
      "feature.preview.desc": "Futtassa a beépített ROM-ot valódi libretro magban, írja be a pad bemenetet, léptessen be a képkockákat, csévélje vissza és ellenőrizze a hangot – anélkül, hogy elhagyná a szerkesztőt.",
      "feature.rom.title": "ROM-folyamat és érvényesítés",
      "feature.rom.desc": "LoROM, HiROM, ExHiROM, MSU-1, FastROM és Mega Drive leképező profilok, fejléc, méret, ellenőrző összeg és SD2SNES készenléti ellenőrzésekkel.",
      "feature.fidelity.title": "Őszinte a hűségről",
      "consoles.eyebrow": "Célok",
      "consoles.title1": "Válassz egy konzolt.",
      "consoles.title2": "A szerkesztő beszéli a nyelvét.",
      "consoles.snes.desc": "PVSnesLib 4.6, 4bpp csempék, 1. mód, OBJ sávok, HDMA színmatematika, BRR minták, SNESMOD zene és LoROM/HiROM/ExHiROM képek MSU-1 támogatással.",
      "consoles.snes.item1": "Stage + sprite + ütközésszerkesztők",
      "consoles.snes.item2": "BRR/SFX és SNESMOD hangbankok",
      "consoles.snes.item3": "ROM ellenőrző összeg és SD2SNES készenlét",
      "consoles.snes.link": "Lásd: SNES kimenet",
      "consoles.md.desc": "SGDK 2.11, H40/H32, 4bpp csomagolt csempék, A/B síkok, hardveres sprite, XGM2 PCM/FM zene, PSG hang és lineáris leképező profilok valódi SEGA fejléccel.",
      "consoles.md.item1": "Natív SGDK projektgenerálás",
      "consoles.md.item2": "YM2612/PSG VGM és PCM SFX",
      "consoles.md.item3": "Sprite/stage import 68000-ért",
      "consoles.md.link": "Lásd: Mega Drive kimenet",
      "ports.eyebrow": "Forrásszintű portok",
      "ports.title1": "Nem bináris fordító.",
      "ports.title2": "Egy második natív építmény.",
      "ports.lede": "A 3,58 MHz-es 68000-et egy 65816 nem tudja valós időben értelmezni, és fordítva. A fork játékonkénti adaptereket szállít, amelyek beolvasják az eredeti eszközöket, és újraépítik a játékot a cél SDK-val szemben.",
      "ports.gothic.desc": "Egy teljes PVSnesLib homebrew átépített SGDK-hoz: eredeti pályaoldalak, ütközés, hősfizika, kardharc, három ellenségtípus, címművészet és zene.",
      "ports.sonic.desc": "EHZ Act 1 átépítették a 65816-hoz: eredeti darabelrendezés, ütközés, gyűrűk, badnikok, rugók, monitorok, hurkok, dugóhúzó, Tails követő és SMPS-eredetű zene.",
      "ports.callout.title": "A platformok közötti exportálás kiindulópont, nem varázslat.",
      "ports.callout.text": "A szerkesztő figyelmeztetést jelenít meg, kézi beállítást kér, és az eredményt a következőképpen hozza létre",
      "pipeline.eyebrow": "Munkafolyamat",
      "pipeline.title1": "Jelenettől patronig",
      "pipeline.title2": "három hurokban.",
      "pipeline.step1.title": "Importálás és szerző",
      "pipeline.step1.desc": "Nyisson meg egy PVSnesLib, WLA-DX vagy SGDK projektet, vagy importáljon egy Godot-jelenetet. Használja a színpad, a sprite, az animáció, a paletta és az ütközésszerkesztőket a játék formálásához.",
      "pipeline.step2.title": "Generálás és építés",
      "pipeline.step2.desc": "A Game Build önálló projektet ír konvertált eszközökkel, kiválasztja a ROM-profilt, futtatja a valódi SDK-t, és ellenőrzi az eredményül kapott képet.",
      "pipeline.step3.title": "Futtassa és ellenőrizze",
      "pipeline.step3.desc": "A ROM valódi emulátormagban indul el. Nyomd meg a gombokat, léptess kereteket, tekerj vissza, nézd meg a hangfolyamot, és javítsd ki, amit az előnézet mutat.",
      "showcase.eyebrow": "Kirakat",
      "showcase.title": "Valódi ROM-ok. Igazi konzolok.",
      "showcase.lede": "Minden alábbi kép egy generált ROM-ból származik, amely a szerkesztő emulátor előnézetében fut.",
      "gallery.ehz": "Sonic 2 · Emerald Hill Act 1",
      "gallery.gothic_title": "Gothicvania · cím",
