      "download.eyebrow": "Letöltés",
      "download.title1": "Kezdje el az építkezést",
      "download.title2": "16 bites hardverhez.",
      "download.lede": "Fogja meg a legújabb szerkesztő buildet, és irányítsa a PVSnesLib vagy SGDK projektre. A villa nyílt forráskódú; a kiadásokat a GitHubon teszik közzé.",
      "download.button": "Letöltés a GitHub-kiadásokon",
      "download.tiny": "Legutóbbi címkézett build: 0.1.60 · Godot 4.7 villa",
      "download.note": "Nincs fiók, nincs telemetria, nincsenek mellékelt ROM-ok. Hozd magaddal legálisan szerzett vagyonod.",
      "faq.eyebrow": "GYIK",
      "faq.title1": "Ön előtt",
      "faq.title2": "helyezze be a patront.",
      "faq.lede": "Rövid válaszok azokra a kérdésekre, amelyeket egy retro port általában felvet.",
      "faq.official.q": "Ez a hivatalos Godot Engine?",
      "faq.official.a": "Nem. A Godot Retro Engine a Godot 4.7 független villája, amely a SNES és a Mega Drive fejlesztésére összpontosít. Nem áll kapcsolatban a Godot Alapítvánnyal, és nem támogatja azt.",
      "faq.convert.q": "Átalakíthat bármilyen SNES vagy Mega Drive játékot?",
      "faq.convert.a": "Nem. A 65816 és 68000 közötti bináris fordítás valós időben nem praktikus. A fork játékonként épített forrásszintű adaptereket használ; A Sonic 2 és a Gothicvania a referencia megvalósítás.",
      "faq.roms.q": "ROM-ok vagy szerzői jog által védett eszközök szerepelnek benne?",
      "faq.roms.a": "Nem. A szerkesztő és az eszközláncok nyílt forráskódúak. Ön biztosítja saját legálisan szerzett forrásprojektjét, eszközeit és ROM-jait. Az eredeti fájlokat az exportőrök soha nem módosítják.",
      "faq.apps.q": "Valóban Windows és macOS alkalmazásokat épít?",
      "faq.apps.a": "Igen. A Linux natívan épül fel. A Windows a MinGW-w64-gyel keresztbe van fordítva. A macOS az osxcross-szal készült univerzális x86_64 + arm64 alkalmazásként. A kiadás archívuma a GitHubon található.",
      "faq.audio.q": "A hang bit pontos?",
      "faq.audio.a": "Nem mindig. Az SNES és az YM2612 hangja valódi konzolformátumokat és eredeti mintákat használ, ahol rendelkezésre állnak, de egyes borítékok, időzítések és átírások csak hozzávetőlegesek.",
      "footer.about": "Független, forrásból elérhető Godot fork 16 bites konzolfejlesztéshez, portoláshoz és érvényesítéshez.",
