      "hero.eyebrow": "Garpu independen Godot 4.7",
      "hero.title1": "Bangun untuk konsol",
      "hero.title2": "yang membesarkanmu.",
      "hero.lede": "Godot Retro Engine adalah fork Godot sumber terbuka gratis untuk membuat, mem-porting, dan memvalidasi game SNES dan Mega Drive. SDK asli, ROM asli, emulator nyata — dengan adaptor tingkat sumber untuk game yang layak mendapatkan lebih dari sekadar terjemahan biner.",
      "hero.download": "Unduh terbaru",
      "hero.explore": "Jelajahi garpu",
      "hero.meta1": "Windows · Linux · macOS",
