      "consoles.md.desc": "SGDK 2.11、H40/H32、4bpp パック タイル、プレーン A/B、ハードウェア スプライト、XGM2 PCM/FM 音楽、PSG サウンド、および実際の SEGA ヘッダーを備えたリニア マッパー プロファイル。",
      "consoles.md.item1": "ネイティブ SGDK プロジェクトの生成",
