      "ports.eyebrow": "ソースレベルのポート",
      "ports.title1": "バイナリトランスレータではありません。",
      "ports.title2": "2 番目のネイティブ ビルド。",
      "ports.lede": "3.58 MHz 68000 は 65816 でリアルタイムに解釈できませんし、その逆も同様です。フォークには、元のアセットを読み取り、ターゲット SDK に対してゲームを再構築するゲームごとのアダプターが同梱されています。",
      "ports.gothic.desc": "SGDK 用に再構築された完全な PVSnesLib 自作: オリジナルのレベル ページ、衝突、ヒーローの物理学、剣での戦闘、3 つの敵のタイプ、タイトル アートと音楽。",
      "ports.sonic.desc": "65816 用に再構築された EHZ Act 1: オリジナルのチャンク レイアウト、コリジョン、リング、バドニク、スプリング、モニター、ループ、コークスクリュー、テイルス フォロワー、SMPS 由来の音楽。",
      "ports.callout.title": "クロスプラットフォームのエクスポートは出発点であり、魔法ではありません。",
      "ports.callout.text": "エディターは警告を表示し、手動調整を求め、結果を次のように作成します。",
      "pipeline.eyebrow": "ワークフロー",
      "pipeline.title1": "シーンからカートリッジまで",
      "pipeline.title2": "3つのループで。",
      "pipeline.step1.title": "インポートと作成",
      "pipeline.step1.desc": "PVSnesLib、WLA-DX、または SGDK プロジェクトを開くか、Godot シーンをインポートします。ステージ、スプライト、アニメーション、パレット、コリジョン エディターを使用してゲームを形作ります。",
      "pipeline.step2.title": "生成して構築する",
      "pipeline.step2.desc": "Game Build は、変換されたアセットを含むスタンドアロン プロジェクトを作成し、ROM プロファイルを選択し、実際の SDK を実行して、結果のイメージを検証します。",
      "pipeline.step3.title": "実行して検証する",
      "pipeline.step3.desc": "ROM は実際のエミュレータ コアで起動します。ボタンを押し、フレームをステップ移動し、巻き戻し、オーディオ ストリームを検査し、プレビューに表示される内容を修正します。",
      "showcase.eyebrow": "ショーケース",
      "showcase.title": "本物のROM。本物のコンソール。",
      "showcase.lede": "以下のすべての画像は、エディターのエミュレーター プレビューで実行されている生成された ROM からのものです。",
      "gallery.ehz": "ソニック2・エメラルドヒル 第1幕",
      "gallery.gothic_title": "ゴシックヴァニア · タイトル",
      "gallery.gothic_gameplay": "ゴシックヴァニア · ゲームプレイ",
