      "gallery.gothic_jump": "ゴシックヴァニア・ジャンプ",
      "download.eyebrow": "ダウンロード",
      "download.title1": "構築を開始する",
      "download.title2": "16ビットハードウェア用。",
      "download.lede": "最新のエディター ビルドを取得し、PVSnesLib または SGDK プロジェクトに指定します。フォークはオープンソースです。リリースは GitHub で公開されます。",
      "download.button": "GitHub でダウンロード",
      "download.tiny": "最新のタグ付きビルド: 0.1.60 · Godot 4.7 フォーク",
      "download.note": "アカウント、テレメトリ、バンドルされた ROM はありません。合法的に取得した自分の資産を持参してください。",
      "faq.eyebrow": "よくある質問",
      "faq.title1": "あなたの前に",
      "faq.title2": "カートリッジを挿入します。",
      "faq.lede": "レトロポートが通常提起する質問に対する短い回答。",
      "faq.official.q": "これは公式の Godot エンジンですか?",
      "faq.official.a": "いいえ、Godot Retro Engine は Godot 4.7 の独立したフォークであり、SNES と Mega Drive の開発に重点を置いています。ゴドー財団とは提携しておらず、ゴドー財団によって承認されていません。",
      "faq.convert.q": "SNES や Mega Drive のゲームを変換できますか?",
      "faq.convert.a": "いいえ。65816 と 68000 の間のバイナリ変換はリアルタイムでは実用的ではありません。フォークは、ゲームごとに構築されたソースレベルのアダプターを使用します。 Sonic 2 と Gothicvania はリファレンス実装です。",
      "faq.roms.q": "ROM や著作権資産は含まれますか?",
      "faq.roms.a": "いいえ。エディターとツールチェーンはオープンソースです。合法的に入手した独自のソース プロジェクト、アセット、ROM を提供します。元のファイルはエクスポーターによって変更されることはありません。",
      "faq.apps.q": "本当に Windows および macOS アプリを構築できるのでしょうか?",
      "faq.apps.a": "はい。 Linux はネイティブに構築されています。 Windows は MinGW-w64 でクロスコンパイルされています。 macOS は、ユニバーサル x86_64 + arm64 アプリとして osxcross で構築されています。リリースのアーカイブは GitHub にあります。",
      "faq.audio.q": "オーディオはビット正確ですか?",
      "faq.audio.a": "いつもではありません。 SNES および YM2612 オーディオは、実際のコンソール フォーマットと、可能な場合はオリジナルのサンプルを使用しますが、一部のエンベロープ、タイミング、転写は近似のままです。",
      "footer.about": "16 ビット コンソールの開発、移植、検証用に、ソースが利用可能な独立した Godot フォーク。",
      "footer.source": "GitHub のソース",
