      "footer.godot_license": "ゴドーライセンス",
      "footer.contributors": "貢献者",
      "footer.copyright": "© 2026 Godot Retro Engine の貢献者。 Godot は、Juan Linietsky、Ariel Manzur、および貢献者の商標です。この独立したフォークは、Godot Foundation と提携または承認されていません。",
      "footer.note": "ROMはバンドルされていません。合法的に取得した自分の資産を持参してください。",
