      "hero.eyebrow": "Godot 4.7의 독립 포크",
      "hero.title1": "콘솔용 빌드",
      "hero.title2": "그게 당신을 키웠어요.",
      "hero.lede": "Godot Retro Engine은 SNES 및 Mega Drive 게임을 빌드, 이식 및 검증하기 위한 무료 오픈 소스 Godot 포크입니다. 실제 SDK, 실제 ROM, 실제 에뮬레이터 - 바이너리 번역 이상의 가치가 있는 게임용 소스 레벨 어댑터가 포함되어 있습니다.",
      "hero.download": "최신 다운로드",
      "hero.explore": "포크 탐색",
      "hero.meta1": "윈도우 · 리눅스 · macOS",
      "hero.meta2": "MIT 라이선스 포크",
      "hero.meta3": "원격 측정 없음",
      "stats.consoles": "대상 콘솔",
      "stats.editors": "레트로 편집자",
      "stats.builds": "데스크탑 빌드",
      "stats.source": "소스 수준 워크플로",
      "features.eyebrow": "포크 기능",
      "features.title1": "편집자 한 명. 콘솔 2개.",
      "features.title2": "블랙박스 제로.",
      "features.lede": "포크는 Godot의 작업 흐름을 유지하고 레트로 프로젝트에 실제로 필요한 부분(툴체인, 자산 변환기, ROM 프로필, 에뮬레이터 피드백 및 게임별 포트 어댑터)을 추가합니다.",
      "feature.build.title": "듀얼 콘솔 게임 빌드",
      "feature.build.desc": "실제 PVSnesLib/SGDK 프로젝트를 생성하고 동일한 편집기에서 재생 가능한 ROM을 빌드합니다. 대상, 매퍼, ROM 프로필 및 스플래시를 선택한 다음 체크섬을 확인합니다.",
      "feature.ports.title": "소스 레벨 게임 포트",
      "feature.ports.desc": "전용 어댑터는 68000 또는 65816 바이너리를 실시간으로 해석하는 대신 다른 CPU에 대한 게임 로직을 재구성합니다. Sonic 2와 Gothicvania가 작업 사례로 제공됩니다.",
      "feature.import.title": "네이티브 장면 가져오기",
      "feature.import.desc": "Godot 장면의 Sprite2D, AnimatedSprite2D, TileMapLayer, 충돌, 카메라 및 UI를 두 콘솔 모두에 대한 휴대용 액터 및 무대 런타임으로 가져옵니다.",
      "feature.editors.title": "레트로 편집자",
      "feature.editors.desc": "스테이지, 스프라이트, 애니메이션, 팔레트, 충돌, 오디오, 입력, 상태 그래프 및 코드 편집기는 하나의 프로젝트 형식과 하나의 빌드 파이프라인을 공유합니다.",
      "feature.audio.title": "콘솔 오디오 워크벤치",
      "feature.audio.desc": "MIDI, 모듈 및 샘플링된 오디오는 SNESMOD/BRR 또는 YM2612/PSG VGM이 됩니다. SFX는 ROM에 도달하기 전에 합성, 변환 및 미리 볼 수 있습니다.",
      "feature.preview.title": "루프의 에뮬레이터",
      "feature.preview.desc": "편집기를 떠나지 않고도 실제 libretro 코어에서 내장된 ROM을 실행하고, 패드 입력을 삽입하고, 프레임을 스텝하고, 되감고, 오디오를 검사할 수 있습니다.",
      "feature.rom.title": "ROM 파이프라인 및 검증",
      "feature.rom.desc": "LoROM, HiROM, ExHiROM, MSU-1, FastROM 및 Mega Drive 매퍼 프로필(헤더, 크기, 체크섬 및 SD2SNES 준비 확인 포함)",
      "feature.fidelity.title": "충실도에 대해 솔직하다",
      "consoles.eyebrow": "대상",
      "consoles.title1": "콘솔을 선택하세요.",
      "consoles.title2": "편집자는 해당 언어를 사용합니다.",
      "consoles.snes.desc": "MSU-1을 지원하는 PVSnesLib 4.6, 4bpp 타일, 모드 1, OBJ 밴드, HDMA 색상 수학, BRR 샘플, SNESMOD 음악 및 LoROM/HiROM/ExHiROM 이미지.",
      "consoles.snes.item1": "스테이지 + 스프라이트 + 충돌 편집기",
      "consoles.snes.item2": "BRR/SFX 및 SNESMOD 사운드뱅크",
      "consoles.snes.item3": "ROM 체크섬 및 SD2SNES 준비",
      "consoles.snes.link": "SNES 출력 보기",
      "consoles.md.desc": "SGDK 2.11, H40/H32, 4bpp 패킹 타일, 평면 A/B, 하드웨어 스프라이트, XGM2 PCM/FM 음악, PSG 사운드 및 실제 SEGA 헤더가 포함된 선형 매퍼 프로필.",
      "consoles.md.item1": "네이티브 SGDK 프로젝트 생성",
      "consoles.md.item2": "YM2612/PSG VGM 및 PCM SFX",
      "consoles.md.item3": "68000에 대한 스프라이트/스테이지 가져오기",
      "consoles.md.link": "메가 드라이브 출력 보기",
      "ports.eyebrow": "소스 수준 포트",
      "ports.title1": "바이너리 번역기가 아닙니다.",
      "ports.title2": "두 번째 네이티브 빌드.",
      "ports.lede": "3.58MHz 68000은 65816에서 실시간으로 해석할 수 없으며 그 반대의 경우도 마찬가지입니다. 포크는 원본 자산을 읽고 대상 SDK에 대해 게임을 다시 빌드하는 게임별 어댑터를 제공합니다.",
      "ports.gothic.desc": "SGDK용으로 재구성된 완전한 PVSnesLib 홈브류: 원본 레벨 페이지, 충돌, 영웅 물리학, 검투, 세 가지 적 유형, 타이틀 아트 및 음악.",
      "ports.sonic.desc": "65816용으로 재구축된 EHZ Act 1: 원래 청크 레이아웃, 충돌, 링, 배드닉, 스프링, 모니터, 루프, 코르크 따개, 테일 팔로워 및 SMPS 파생 음악.",
      "ports.callout.title": "크로스 플랫폼 내보내기는 마법이 아닌 시작점입니다.",
      "ports.callout.text": "편집기는 경고를 표시하고 수동 조정을 요청하며 다음과 같은 결과를 생성합니다.",
      "pipeline.eyebrow": "작업 흐름",
      "pipeline.title1": "장면에서 카트리지까지",
      "pipeline.title2": "세 개의 루프로.",
      "pipeline.step1.title": "가져오기 및 작성자",
      "pipeline.step1.desc": "PVSnesLib, WLA-DX 또는 SGDK 프로젝트를 열거나 Godot 장면을 가져옵니다. 스테이지, 스프라이트, 애니메이션, 팔레트 및 충돌 편집기를 사용하여 게임을 구성하세요.",
      "pipeline.step2.title": "생성 및 빌드",
      "pipeline.step2.desc": "게임 빌드는 변환된 자산으로 독립형 프로젝트를 작성하고, ROM 프로필을 선택하고, 실제 SDK를 실행하고 결과 이미지의 유효성을 검사합니다.",
      "pipeline.step3.title": "실행 및 확인",
      "pipeline.step3.desc": "ROM은 실제 에뮬레이터 코어에서 부팅됩니다. 버튼을 누르고, 프레임을 이동하고, 되감고, 오디오 스트림을 검사하고, 미리보기에 표시되는 내용을 수정하세요.",
      "showcase.eyebrow": "쇼케이스",
      "showcase.title": "실제 ROM. 실제 콘솔.",
      "showcase.lede": "아래의 모든 이미지는 편집기의 에뮬레이터 미리보기에서 실행되는 생성된 ROM에서 가져온 것입니다.",
      "gallery.ehz": "소닉 2 · 에메랄드 힐 액트 1",
