      "nav.download": "ດາວໂຫຼດ",
      "hero.eyebrow": "ສ້ອມເອກະລາດຂອງ Godot 4.7",
      "hero.title1": "ສ້າງສໍາລັບ consoles ໄດ້",
      "hero.title2": "ທີ່ຍົກຂຶ້ນມາທ່ານ.",
      "hero.lede": "Godot Retro Engine ເປັນເຄື່ອງສ້ອມ Godot ທີ່ບໍ່ເສຍຄ່າ, ແຫຼ່ງເປີດສໍາລັບການກໍ່ສ້າງ, porting ແລະກວດສອບເກມ SNES ແລະ Mega Drive. SDKs ທີ່ແທ້ຈິງ, ROMs ທີ່ແທ້ຈິງ, emulators ທີ່ແທ້ຈິງ — ມີອະແດບເຕີລະດັບແຫຼ່ງສໍາລັບເກມທີ່ສົມຄວນໄດ້ຮັບຫຼາຍກ່ວາການແປພາສາຄູ່.",
