      "stats.builds": "ການສ້າງ desktop",
      "stats.source": "ຂັ້ນຕອນການເຮັດວຽກລະດັບແຫຼ່ງ",
      "features.eyebrow": "ຄຸນສົມບັດຂອງສ້ອມ",
      "features.title1": "ບັນນາທິການຫນຶ່ງ. ສອງ consoles.",
      "features.title2": "ສູນກ່ອງດຳ.",
      "features.lede": "ສ້ອມຮັກສາຂະບວນການເຮັດວຽກຂອງ Godot ແລະເພີ່ມພາກສ່ວນທີ່ໂຄງການ retro ຕ້ອງການ: ເຄື່ອງມື, ຕົວແປງຊັບສິນ, ໂປຼໄຟລ໌ ROM, ຄໍາຄຶດຄໍາເຫັນຂອງ emulator ແລະອະແດບເຕີພອດເກມສະເພາະ.",
      "feature.build.title": "ການສ້າງເກມສອງຄອນໂຊນ",
      "feature.build.desc": "ສ້າງໂຄງການ PVSnesLib/SGDK ທີ່ແທ້ຈິງ ແລະສ້າງ ROM ທີ່ສາມາດຫຼິ້ນໄດ້ຈາກບັນນາທິການດຽວກັນ. ເລືອກເປົ້າຫມາຍ, mapper, ROM profile ແລະ splash, ຫຼັງຈາກນັ້ນກວດສອບ checksum.",
      "feature.ports.title": "ພອດເກມລະດັບແຫຼ່ງ",
      "feature.ports.desc": "ອະແດັບເຕີທີ່ອຸທິດຕົນສ້າງເຫດຜົນເກມໃຫ້ກັບ CPU ອື່ນແທນການຕີຄວາມໝາຍຂອງຄູ່ 68000 ຫຼື 65816 ໃນເວລາຈິງ. ເຮືອ Sonic 2 ແລະ Gothicvania ເປັນຕົວຢ່າງທີ່ເຮັດວຽກ.",
      "feature.import.title": "ການນໍາເຂົ້າ scene ພື້ນເມືອງ",
      "feature.import.desc": "ເອົາ Sprite2D, AnimatedSprite2D, TileMapLayer, collisions, ກ້ອງຖ່າຍຮູບແລະ UI ຈາກ scene Godot ເຂົ້າໄປໃນນັກສະແດງ Portable ແລະ runtime ເວທີສໍາລັບທັງສອງ consoles.",
      "feature.editors.title": "ບັນນາທິການ Retro",
      "feature.editors.desc": "ຂັ້ນຕອນ, sprite, ພາບເຄື່ອນໄຫວ, palette, collision, ສຽງ, ວັດສະດຸປ້ອນ, ເສັ້ນສະແດງຂອງລັດແລະລະຫັດບັນນາທິການແບ່ງປັນຮູບແບບໂຄງການຫນຶ່ງແລະສ້າງທໍ່ຫນຶ່ງ.",
      "feature.audio.title": "Console workbench ສຽງ",
      "feature.audio.desc": "MIDI, ໂມດູນ ແລະສຽງຕົວຢ່າງກາຍເປັນ SNESMOD/BRR ຫຼື YM2612/PSG VGM. SFX ສາມາດຖືກສັງເຄາະ, ແປງແລະສະແດງຕົວຢ່າງກ່ອນທີ່ມັນຈະມາຮອດ ROM.",
      "feature.preview.title": "Emulator ໃນ loop ໄດ້",
      "feature.preview.desc": "ແລ່ນ ROM ທີ່ສ້າງຂຶ້ນໃນຫຼັກ libretro ທີ່ແທ້ຈິງ, ປ້ອນຂໍ້ມູນໃສ່ pad, ກອບຂັ້ນຕອນ, rewind ແລະກວດສອບສຽງ — ໂດຍບໍ່ມີການອອກຈາກບັນນາທິການ.",
      "feature.rom.title": "ROM pipeline & ການກວດສອບ",
      "feature.rom.desc": "LoROM, HiROM, ExHiROM, MSU-1, FastROM ແລະ Mega Drive mapper profile, ມີ header, size, checksum ແລະ SD2SNES ການກວດສອບຄວາມພ້ອມ.",
      "feature.fidelity.title": "ຊື່ສັດກ່ຽວກັບຄວາມຊື່ສັດ",
      "consoles.eyebrow": "ເປົ້າໝາຍ",
      "consoles.title1": "ເລືອກ console.",
      "consoles.title2": "ບັນນາທິການເວົ້າພາສາຂອງຕົນ.",
      "consoles.snes.desc": "PVSnesLib 4.6, 4bpp tiles, Mode 1, OBJ bands, HDMA color math, BRR samples, SNESMOD music ແລະ LoROM/HiROM/ExHiROM ຮູບພາບທີ່ຮອງຮັບ MSU-1.",
      "consoles.snes.item1": "ຂັ້ນຕອນ + sprite + collision ບັນນາທິການ",
      "consoles.snes.item2": "BRR/SFX ແລະ SNESMOD soundbanks",
      "consoles.snes.item3": "ROM checksum ແລະຄວາມພ້ອມ SD2SNES",
      "consoles.snes.link": "ເບິ່ງຜົນຜະລິດ SNES",
      "consoles.md.desc": "SGDK 2.11, H40/H32, 4bpp packed tiles, planes A/B, hardware sprites, XGM2 PCM/FM music, PSG sound and linear mapper profile with a real SEGA header.",
      "consoles.md.item1": "ການຜະລິດໂຄງການ SGDK ພື້ນເມືອງ",
      "consoles.md.item2": "YM2612/PSG VGM ແລະ PCM SFX",
