      "feature.import.desc": "Traga Sprite2D, AnimatedSprite2D, TileMapLayer, colisões, câmeras e UI de uma cena Godot para um ator portátil e tempo de execução de palco para ambos os consoles.",
      "feature.editors.title": "Editores retrô",
      "feature.editors.desc": "Os editores de palco, sprite, animação, paleta, colisão, áudio, entrada, gráfico de estado e código compartilham um formato de projeto e um pipeline de construção.",
      "feature.audio.title": "Bancada de áudio do console",
      "feature.audio.desc": "MIDI, módulo e áudio amostrado tornam-se SNESMOD/BRR ou YM2612/PSG VGM. SFX pode ser sintetizado, convertido e visualizado antes de chegar à ROM.",
      "feature.preview.title": "Emulador em loop",
      "feature.preview.desc": "Execute a ROM construída em um núcleo de libretro real, injete entrada de pad, avance quadros, rebobine e inspecione o áudio - sem sair do editor.",
      "feature.rom.title": "Pipeline e validação de ROM",
      "feature.rom.desc": "Perfis de mapeadores LoROM, HiROM, ExHiROM, MSU-1, FastROM e Mega Drive, com verificações de cabeçalho, tamanho, checksum e prontidão SD2SNES.",
      "feature.fidelity.title": "Honesto sobre fidelidade",
      "consoles.eyebrow": "Alvos",
      "consoles.title1": "Escolha um console.",
      "consoles.title2": "O editor fala sua língua.",
      "consoles.snes.desc": "PVSnesLib 4.6, blocos de 4bpp, Modo 1, bandas OBJ, matemática de cores HDMA, amostras BRR, música SNESMOD e imagens LoROM/HiROM/ExHiROM com suporte MSU-1.",
      "consoles.snes.item1": "Editores de palco + sprite + colisão",
      "consoles.snes.item2": "Bancos de som BRR/SFX e SNESMOD",
      "consoles.snes.item3": "Soma de verificação de ROM e prontidão para SD2SNES",
      "consoles.snes.link": "Veja a saída SNES",
      "consoles.md.desc": "SGDK 2.11, H40/H32, blocos compactados de 4bpp, planos A/B, sprites de hardware, música XGM2 PCM/FM, som PSG e perfis de mapeador linear com um cabeçalho SEGA real.",
      "consoles.md.item1": "Geração de projeto SGDK nativo",
      "consoles.md.item2": "YM2612/PSG VGM e PCM SFX",
      "consoles.md.item3": "Importação de Sprite/estágio para 68.000",
      "consoles.md.link": "Veja a saída do Mega Drive",
      "ports.eyebrow": "Portas de nível de origem",
      "ports.title1": "Não é um tradutor binário.",
      "ports.title2": "Uma segunda compilação nativa.",
      "ports.lede": "Um 68000 de 3,58 MHz não pode ser interpretado por um 65816 em tempo real e vice-versa. O fork fornece adaptadores por jogo que leem os ativos originais e reconstroem o jogo no SDK de destino.",
      "ports.gothic.desc": "Um homebrew PVSnesLib completo reconstruído para SGDK: páginas de nível original, colisão, física do herói, combate com espadas, três tipos de inimigos, arte do título e música.",
      "ports.sonic.desc": "EHZ Act 1 reconstruído para o 65816: layout de pedaço original, colisão, anéis, badniks, molas, monitores, loops, saca-rolhas, seguidor de Tails e música derivada de SMPS.",
      "ports.callout.title": "A exportação entre plataformas é um ponto de partida, não uma mágica.",
      "ports.callout.text": "O editor mostra um aviso, pede ajustes manuais e cria o resultado conforme",
      "pipeline.eyebrow": "Fluxo de trabalho",
      "pipeline.title1": "Da cena ao cartucho",
      "pipeline.title2": "em três voltas.",
      "pipeline.step1.title": "Importar e criar",
      "pipeline.step1.desc": "Abra um projeto PVSnesLib, WLA-DX ou SGDK ou importe uma cena Godot. Use os editores de palco, sprite, animação, paleta e colisão para moldar o jogo.",
      "pipeline.step2.title": "Gerar e construir",
      "pipeline.step2.desc": "Game Build escreve um projeto independente com ativos convertidos, escolhe o perfil ROM, executa o SDK real e valida a imagem resultante.",
      "pipeline.step3.title": "Execute e verifique",
      "pipeline.step3.desc": "A ROM inicializa em um núcleo de emulador real. Pressione botões, avance quadros, retroceda, inspecione o fluxo de áudio e corrija o que a visualização mostra.",
      "showcase.eyebrow": "Vitrine",
      "showcase.title": "ROMs reais. Consolas reais.",
      "showcase.lede": "Cada imagem abaixo vem de uma ROM gerada rodando na visualização do emulador do editor.",
      "gallery.ehz": "Sonic 2 · Emerald Hill Ato 1",
      "gallery.gothic_title": "Gothicvania · título",
      "gallery.gothic_gameplay": "Gothicvania · jogabilidade",
      "gallery.sonic_corkscrew": "Sonic 2 · saca-rolhas",
      "gallery.gothic_jump": "Gothicvania · pular",
      "download.eyebrow": "Baixar",
      "download.title1": "Comece a construir",
      "download.title2": "para hardware de 16 bits.",
      "download.lede": "Pegue a versão mais recente do editor e aponte-a para seu projeto PVSnesLib ou SGDK. O fork é de código aberto; lançamentos são publicados no GitHub.",
      "download.button": "Baixe no GitHub Lançamentos",
      "download.tiny": "Última compilação marcada: 0.1.60 · Godot 4.7 fork",
      "download.note": "Sem conta, sem telemetria, sem ROMs incluídas. Traga seus próprios bens obtidos legalmente.",
      "faq.eyebrow": "Perguntas frequentes",
      "faq.title1": "Antes de você",
      "faq.title2": "insira o cartucho.",
      "faq.lede": "Respostas curtas às perguntas que uma porta retro normalmente levanta.",
      "faq.official.q": "Este é o motor Godot oficial?",
      "faq.official.a": "Godot Retro Engine é um fork independente do Godot 4.7, focado no desenvolvimento de SNES e Mega Drive. Não é afiliado ou endossado pela Fundação Godot.",
      "faq.convert.q": "Ele pode converter qualquer jogo de SNES ou Mega Drive?",
      "faq.convert.a": "Não. A tradução binária entre 65816 e 68000 não é prática em tempo real. O fork usa adaptadores de nível de origem criados por jogo; Sonic 2 e Gothicvania são as implementações de referência.",
      "faq.roms.q": "ROMs ou ativos protegidos por direitos autorais estão incluídos?",
      "faq.roms.a": "Não. O editor e as cadeias de ferramentas são de código aberto. Você fornece seu próprio projeto de origem, ativos e ROMs obtidos legalmente. Os arquivos originais nunca são modificados pelos exportadores.",
      "faq.apps.q": "Ele realmente cria aplicativos para Windows e macOS?",
      "faq.apps.a": "Sim. O Linux é construído nativamente. O Windows é compilado cruzadamente com MinGW-w64. O macOS foi desenvolvido com osxcross como um aplicativo universal x86_64 + arm64. Os arquivos de lançamento estão no GitHub.",
      "faq.audio.q": "O áudio é exato?",
      "faq.audio.a": "Nem sempre. O áudio SNES e YM2612 usam formatos de console reais e amostras originais quando disponíveis, mas alguns envelopes, tempos e transcrições permanecem aproximações.",
      "footer.about": "Um fork Godot independente e disponível na fonte para desenvolvimento, portabilidade e validação de console de 16 bits.",
      "footer.source": "Fonte no GitHub",
      "footer.engine": "Motor",
      "footer.project": "Projeto",
      "footer.repository": "Repositório",
      "footer.releases": "Lançamentos",
      "footer.legal": "Jurídico",
      "footer.license": "Licença",
      "footer.godot_license": "Licença Godot",
      "footer.contributors": "Colaboradores",
