      "hero.lede": "Godot Retro Engine este o furcă Godot gratuită, open-source, pentru construirea, portarea și validarea jocurilor SNES și Mega Drive. SDK-uri reale, ROM-uri reale, emulatoare reale — cu adaptoare la nivel de sursă pentru jocurile care merită mai mult decât o traducere binară.",
