      "consoles.md.desc": "SGDK 2.11, H40/H32, țigle împachetate 4bpp, avioane A/B, sprite hardware, muzică XGM2 PCM/FM, sunet PSG și profile liniar mapper cu un antet SEGA real.",
      "consoles.md.item1": "Generare nativă de proiecte SGDK",
