      "faq.official.q": "Acesta este Motorul Godot oficial?",
      "faq.official.a": "Nu. Godot Retro Engine este o furcă independentă a Godot 4.7, axată pe dezvoltarea SNES și Mega Drive. Nu este afiliat sau susținut de Fundația Godot.",
      "faq.convert.q": "Poate converti orice joc SNES sau Mega Drive?",
      "faq.convert.a": "Nu. Traducerea binară între 65816 și 68000 nu este practică în timp real. Furca utilizează adaptoare la nivel de sursă construite pentru fiecare joc; Sonic 2 și Gothicvania sunt implementările de referință.",
      "faq.roms.q": "Sunt incluse ROM-urile sau activele protejate prin drepturi de autor?",
      "faq.roms.a": "Nu. Editorul și lanțurile de instrumente sunt open source. Vă furnizați propriul proiect sursă, active și ROM-uri obținute legal. Fișierele originale nu sunt niciodată modificate de către exportatori.",
