      "hero.title2": "som uppfostrade dig.",
      "hero.lede": "Godot Retro Engine är en gratis Godot-gaffel med öppen källkod för att bygga, portera och validera SNES- och Mega Drive-spel. Riktiga SDK:er, riktiga ROM:er, riktiga emulatorer - med adaptrar på källnivå för spelen som förtjänar mer än en binär översättning.",
      "hero.download": "Ladda ner senaste",
      "hero.explore": "Utforska gaffeln",
      "hero.meta1": "Windows · Linux · macOS",
