      "features.eyebrow": "Gaffelfunktioner",
      "features.title1": "En redaktör. Två konsoler.",
      "features.title2": "Noll svarta lådor.",
      "features.lede": "Gaffeln håller Godots arbetsflöde och lägger till de delar som ett retroprojekt faktiskt behöver: verktygskedjor, tillgångsomvandlare, ROM-profiler, emulatorfeedback och spelspecifika portadaptrar.",
      "feature.build.title": "Spelbyggd med dubbla konsoler",
      "feature.build.desc": "Skapa ett riktigt PVSnesLib/SGDK-projekt och bygg ett spelbart ROM från samma editor. Välj mål, mappar, ROM-profil och splash och validera sedan kontrollsumman.",
      "feature.ports.title": "Spelportar på källnivå",
      "feature.ports.desc": "Dedikerade adaptrar bygger om spellogik för den andra CPU:n istället för att tolka en 68000 eller 65816 binär i realtid. Sonic 2 och Gothicvania levereras som fungerande exempel.",
      "feature.import.title": "Import av ursprunglig scen",
      "feature.import.desc": "Ta Sprite2D, AnimatedSprite2D, TileMapLayer, kollisioner, kameror och UI från en Godot-scen till en bärbar skådespelare och scentid för båda konsolerna.",
      "feature.editors.title": "Retro redaktörer",
      "feature.editors.desc": "Scen-, sprite-, animations-, palett-, kollision-, ljud-, input-, tillståndsgraf- och kodredigerare delar ett projektformat och en byggpipeline.",
      "feature.audio.title": "Konsol ljud arbetsbänk",
      "feature.audio.desc": "MIDI, modul och samplade ljud blir SNESMOD/BRR eller YM2612/PSG VGM. SFX kan syntetiseras, konverteras och förhandsgranskas innan de når ROM.",
      "feature.preview.title": "Emulator i slingan",
      "feature.preview.desc": "Kör det inbyggda ROM-minnet i en riktig libretro-kärna, injicera pad-ingång, stegramar, spola tillbaka och inspektera ljud - utan att lämna redigeraren.",
      "feature.rom.title": "ROM pipeline & validering",
      "feature.rom.desc": "LoROM, HiROM, ExHiROM, MSU-1, FastROM och Mega Drive mappningsprofiler, med header, size, checksum och SD2SNES beredskapskontroller.",
      "feature.fidelity.title": "Ärlig om trohet",
      "consoles.eyebrow": "Mål",
      "consoles.title1": "Välj en konsol.",
      "consoles.title2": "Redaktören talar sitt språk.",
      "consoles.snes.desc": "PVSnesLib 4.6, 4bpp-plattor, läge 1, OBJ-band, HDMA-färgmatematik, BRR-prover, SNESMOD-musik och LoROM/HiROM/ExHiROM-bilder med MSU-1-stöd.",
      "consoles.snes.item1": "Stage + sprite + kollisionsredigerare",
      "consoles.snes.item2": "BRR/SFX och SNESMOD ljudbanker",
      "consoles.snes.item3": "ROM-kontrollsumma och SD2SNES-beredskap",
      "consoles.snes.link": "Se SNES-utgång",
      "consoles.md.desc": "SGDK 2.11, H40/H32, 4bpp packade brickor, plan A/B, hårdvarusprites, XGM2 PCM/FM-musik, PSG-ljud och linjära mapparprofiler med en riktig SEGA-header.",
      "consoles.md.item1": "Native SGDK-projektgenerering",
      "consoles.md.item2": "YM2612/PSG VGM och PCM SFX",
      "consoles.md.item3": "Sprite/stage import för 68000",
      "consoles.md.link": "Se Mega Drive-utgång",
      "ports.eyebrow": "Portar på källnivå",
      "ports.title1": "Inte en binär översättare.",
      "ports.title2": "En andra inbyggd konstruktion.",
      "ports.lede": "En 3,58 MHz 68000 kan inte tolkas av en 65816 i realtid, och vice versa. Gaffeln skickar adaptrar per spel som läser de ursprungliga tillgångarna och bygger om spelet mot mål-SDK:n.",
      "ports.gothic.desc": "En komplett PVSnesLib-hembryggning ombyggd för SGDK: originalnivåsidor, kollision, hjältefysik, svärdstrid, tre fiendetyper, titelkonst och musik.",
      "ports.sonic.desc": "EHZ Act 1 ombyggd för 65816: original chunk-layout, kollision, ringar, badniks, fjädrar, monitorer, loopar, korkskruv, Tails-följare och SMPS-härledd musik.",
      "ports.callout.title": "Export över plattformar är en utgångspunkt, inte magi.",
      "ports.callout.text": "Redaktören visar en varning, ber om manuella justeringar och skapar resultatet som",
      "pipeline.eyebrow": "Arbetsflöde",
      "pipeline.title1": "Från scen till patron",
      "pipeline.title2": "i tre slingor.",
      "pipeline.step1.title": "Importera & författare",
      "pipeline.step1.desc": "Öppna ett PVSnesLib-, WLA-DX- eller SGDK-projekt eller importera en Godot-scen. Använd scen-, sprite-, animations-, palett- och kollisionsredigerare för att forma spelet.",
      "pipeline.step2.title": "Generera & bygg",
      "pipeline.step2.desc": "Game Build skriver ett fristående projekt med konverterade tillgångar, väljer ROM-profilen, kör den riktiga SDK:n och validerar den resulterande bilden.",
      "pipeline.step3.title": "Kör och verifiera",
      "pipeline.step3.desc": "ROM:en startar i en riktig emulatorkärna. Tryck på knappar, stega ramar, spola tillbaka, inspektera ljudströmmen och fixa det som förhandsgranskningen visar dig.",
      "showcase.eyebrow": "Showcase",
      "showcase.title": "Riktiga ROM. Riktiga konsoler.",
      "showcase.lede": "Varje bild nedan kommer från ett genererat ROM som körs i redigerarens emulatorförhandsvisning.",
      "gallery.ehz": "Sonic 2 · Emerald Hill Akt 1",
      "gallery.gothic_title": "Gothicvania · titel",
      "gallery.gothic_gameplay": "Gothicvania · spel",
      "gallery.sonic_corkscrew": "Sonic 2 · korkskruv",
      "gallery.gothic_jump": "Gothicvania · hoppa",
      "download.eyebrow": "Ladda ner",
      "download.title1": "Börja bygga",
      "download.title2": "för 16-bitars hårdvara.",
      "download.lede": "Ta tag i den senaste redigeraren och rikta den mot ditt PVSnesLib- eller SGDK-projekt. Gaffeln är öppen källkod; releaser publiceras på GitHub.",
      "download.button": "Ladda ner på GitHub-versioner",
      "download.tiny": "Senaste taggade bygget: 0.1.60 · Godot 4.7 gaffel",
      "download.note": "Inget konto, ingen telemetri, inga medföljande ROM. Ta med egna lagligt erhållna tillgångar.",
      "faq.eyebrow": "FAQ",
      "faq.title1": "Före dig",
      "faq.title2": "sätt i patronen.",
      "faq.lede": "Korta svar på frågorna en retroport brukar väcker.",
      "faq.official.q": "Är detta den officiella Godot-motorn?",
      "faq.official.a": "Nej. Godot Retro Engine är en oberoende gaffel av Godot 4.7, fokuserad på SNES och Mega Drive-utveckling. Den är inte ansluten till eller godkänd av Godot Foundation.",
      "faq.convert.q": "Kan det konvertera vilket SNES- eller Mega Drive-spel som helst?",
      "faq.convert.a": "Nej. Binär översättning mellan 65816 och 68000 är inte praktiskt i realtid. Gaffeln använder adaptrar på källnivå som är byggda per spel; Sonic 2 och Gothicvania är referensimplementeringarna.",
      "faq.roms.q": "Ingår ROM-skivor eller upphovsrättsskyddade tillgångar?",
      "faq.roms.a": "Nej. Redaktören och verktygskedjorna är öppen källkod. Du tillhandahåller ditt eget lagligt erhållna källprojekt, tillgångar och ROM. Originalfilerna ändras aldrig av exportörerna.",
      "faq.apps.q": "Bygger det verkligen Windows- och macOS-appar?",
      "faq.apps.a": "Ja. Linux är byggt inbyggt. Windows är korskompilerat med MinGW-w64. macOS är byggt med osxcross som en universell x86_64 + arm64-app. Utgivningsarkiv finns på GitHub.",
      "faq.audio.q": "Är ljudet bitexakt?",
      "faq.audio.a": "Inte alltid. SNES- och YM2612-ljud använder riktiga konsolformat och originalexempel där sådana finns, men vissa kuvert, timing och transkriptioner förblir ungefärliga.",
      "footer.about": "En oberoende, källtillgänglig Godot-gaffel för 16-bitars konsolutveckling, portering och validering.",
      "footer.source": "Källa på GitHub",
      "footer.engine": "Motor",
      "footer.project": "Projekt",
      "footer.repository": "Förvar",
      "footer.releases": "Släpps",
      "footer.legal": "Lagligt",
      "footer.license": "Licens",
      "footer.godot_license": "Godot licens",
      "footer.contributors": "Bidragsgivare",
      "footer.copyright": "© 2026 Godot Retro Engine-bidragsgivare. Godot är ett varumärke som tillhör Juan Linietsky, Ariel Manzur och bidragsgivare. Denna oberoende gaffel är inte ansluten till eller godkänd av Godot Foundation.",
      "footer.note": "Inga ROM-skivor medföljer. Ta med egna lagligt erhållna tillgångar.",
      "feature.fidelity.desc": "Export över plattformar varnar dig när manuellt arbete krävs, och genererade projekt heter {{SNES}} / {{MD}} så att de aldrig förväxlas med källan.",
      "nav.language": "Språk",
