      "hero.eyebrow": "ทางแยกอิสระของ Godot 4.7",
      "hero.title1": "สร้างสำหรับคอนโซล",
      "hero.title2": "ที่เลี้ยงดูคุณ",
      "hero.lede": "Godot Retro Engine เป็น Godot fork แบบโอเพ่นซอร์สฟรีสำหรับสร้าง ย้าย และตรวจสอบเกม SNES และ Mega Drive SDK จริง, ROM จริง, โปรแกรมจำลองจริง — พร้อมอะแดปเตอร์ระดับซอร์สสำหรับเกมที่สมควรได้รับมากกว่าการแปลไบนารี",
