      "features.eyebrow": "คุณสมบัติส้อม",
      "features.title1": "บรรณาธิการคนหนึ่ง สองคอนโซล",
      "features.title2": "กล่องดำเป็นศูนย์",
      "features.lede": "ทางแยกจะเก็บเวิร์กโฟลว์ของ Godot และเพิ่มส่วนที่โปรเจ็กต์ย้อนยุคต้องการจริงๆ: ห่วงโซ่เครื่องมือ ตัวแปลงสินทรัพย์ โปรไฟล์ ROM ความคิดเห็นของโปรแกรมจำลอง และอะแดปเตอร์พอร์ตเฉพาะเกม",
      "feature.build.title": "การสร้างเกมคอนโซลคู่",
      "feature.build.desc": "สร้างโปรเจ็กต์ PVSnesLib/SGDK จริงและสร้าง ROM ที่สามารถเล่นได้จากโปรแกรมแก้ไขเดียวกัน เลือกเป้าหมาย ผู้ทำแผนที่ โปรไฟล์ ROM และสแปลช จากนั้นตรวจสอบความถูกต้องของผลรวม",
      "feature.ports.title": "พอร์ตเกมระดับแหล่งที่มา",
      "feature.ports.desc": "อะแดปเตอร์เฉพาะสร้างตรรกะของเกมใหม่สำหรับ CPU อื่น แทนที่จะตีความไบนารี 68000 หรือ 65816 แบบเรียลไทม์ Sonic 2 และ Gothicvania จัดส่งเป็นตัวอย่างการทำงาน",
      "feature.import.title": "การนำเข้าฉากดั้งเดิม",
      "feature.import.desc": "นำ Sprite2D, AnimatedSprite2D, TileMapLayer, การชนกัน, กล้อง และ UI จากฉาก Godot มาสู่นักแสดงแบบพกพาและรันไทม์บนเวทีสำหรับคอนโซลทั้งสองเครื่อง",
      "feature.editors.title": "บรรณาธิการย้อนยุค",
