      "feature.audio.desc": "MIDI, โมดูล และเสียงตัวอย่างจะกลายเป็น SNESMOD/BRR หรือ YM2612/PSG VGM SFX สามารถสังเคราะห์ แปลง และดูตัวอย่างได้ก่อนที่จะถึง ROM",
      "feature.preview.title": "โปรแกรมจำลองในวง",
      "feature.preview.desc": "รัน ROM ที่สร้างขึ้นในคอร์ libretro จริง ใส่อินพุตแพด สเต็ปเฟรม กรอกลับและตรวจสอบเสียง โดยไม่ต้องออกจากโปรแกรมแก้ไข",
