      "faq.lede": "คำตอบสั้น ๆ สำหรับคำถามที่พอร์ตย้อนยุคมักจะถาม",
      "faq.official.q": "นี่คือ Godot Engine อย่างเป็นทางการใช่ไหม",
      "faq.official.a": "ไม่ Godot Retro Engine เป็นทางแยกอิสระของ Godot 4.7 ที่เน้นไปที่การพัฒนา SNES และ Mega Drive มันไม่มีส่วนเกี่ยวข้องหรือรับรองโดยมูลนิธิ Godot",
      "faq.convert.q": "สามารถแปลงเกม SNES หรือ Mega Drive ได้หรือไม่",
      "faq.convert.a": "ไม่ การแปลไบนารี่ระหว่าง 65816 ถึง 68000 ไม่สามารถทำได้แบบเรียลไทม์ ทางแยกใช้อะแดปเตอร์ระดับแหล่งที่มาที่สร้างขึ้นต่อเกม Sonic 2 และ Gothicvania เป็นการใช้งานอ้างอิง",
      "faq.roms.q": "ROM หรือทรัพย์สินที่มีลิขสิทธิ์รวมอยู่ด้วยหรือไม่",
      "faq.roms.a": "ไม่ ตัวแก้ไขและ toolchains เป็นโอเพ่นซอร์ส คุณจัดหาโปรเจ็กต์แหล่งที่มา สินทรัพย์ และ ROM ที่ได้รับมาตามกฎหมายของคุณเอง ไฟล์ต้นฉบับจะไม่ถูกแก้ไขโดยผู้ส่งออก",
      "faq.apps.q": "มันสร้างแอพ Windows และ macOS จริง ๆ หรือไม่?",
      "faq.apps.a": "ใช่. Linux ถูกสร้างขึ้นโดยกำเนิด Windows ถูกคอมไพล์ข้ามด้วย MinGW-w64 macOS สร้างขึ้นด้วย osxcross เป็นแอปสากล x86_64 + arm64 คลังข้อมูลการเผยแพร่อยู่บน GitHub",
      "faq.audio.q": "บิตของเสียงนั้นแม่นยำหรือไม่?",
      "faq.audio.a": "ไม่เสมอไป เสียง SNES และ YM2612 ใช้รูปแบบคอนโซลจริงและตัวอย่างต้นฉบับ หากมี แต่ซองจดหมาย จังหวะเวลา และการถอดเสียงบางส่วนยังคงเป็นการประมาณค่า",
      "footer.about": "Godot fork อิสระและพร้อมใช้งานจากแหล่งที่มาสำหรับการพัฒนาคอนโซล 16 บิต การย้ายพอร์ต และการตรวจสอบความถูกต้อง",
