      "hero.eyebrow": "Independent fork of Godot 4.7",
      "hero.title1": "Build for the consoles",
      "hero.title2": "that raised you.",
      "hero.lede": "Godot Retro Engine is a free, open-source Godot fork for building, porting and validating SNES and Mega Drive games. Real SDKs, real ROMs, real emulators — with source-level adapters for the games that deserve more than a binary translation.",
      "hero.download": "Download latest",
      "hero.explore": "Explore the fork",
      "hero.meta1": "Windows · Linux · macOS",
      "hero.meta2": "MIT-licensed fork",
      "hero.meta3": "No telemetry",
      "stats.consoles": "target consoles",
      "stats.editors": "retro editors",
      "stats.builds": "desktop builds",
      "stats.source": "source-level workflows",
      "features.eyebrow": "Fork features",
      "features.title1": "One editor. Two consoles.",
      "features.title2": "Zero black boxes.",
      "features.lede": "The fork keeps Godot's workflow and adds the parts a retro project actually needs: toolchains, asset converters, ROM profiles, emulator feedback and game-specific port adapters.",
      "feature.build.title": "Dual-console Game Build",
      "feature.build.desc": "Generate a real PVSnesLib/SGDK project and build a playable ROM from the same editor. Choose the target, mapper, ROM profile and splash, then validate the checksum.",
      "feature.ports.title": "Source-level game ports",
      "feature.ports.desc": "Dedicated adapters rebuild game logic for the other CPU instead of interpreting a 68000 or 65816 binary in real time. Sonic 2 and Gothicvania ship as working examples.",
      "feature.import.title": "Native scene import",
      "feature.import.desc": "Bring Sprite2D, AnimatedSprite2D, TileMapLayer, collisions, cameras and UI from a Godot scene into a portable actor and stage runtime for both consoles.",
      "feature.editors.title": "Retro editors",
      "feature.editors.desc": "Stage, sprite, animation, palette, collision, audio, input, state graph and code editors share one project format and one build pipeline.",
      "feature.audio.title": "Console audio workbench",
      "feature.audio.desc": "MIDI, module and sampled audio become SNESMOD/BRR or YM2612/PSG VGM. SFX can be synthesized, converted and previewed before they reach the ROM.",
      "feature.preview.title": "Emulator in the loop",
      "feature.preview.desc": "Run the built ROM in a real libretro core, inject pad input, step frames, rewind and inspect audio — without leaving the editor.",
      "feature.rom.title": "ROM pipeline & validation",
      "feature.rom.desc": "LoROM, HiROM, ExHiROM, MSU-1, FastROM and Mega Drive mapper profiles, with header, size, checksum and SD2SNES readiness checks.",
      "feature.fidelity.title": "Honest about fidelity",
      "consoles.eyebrow": "Targets",
      "consoles.title1": "Pick a console.",
      "consoles.title2": "The editor speaks its language.",
      "consoles.snes.desc": "PVSnesLib 4.6, 4bpp tiles, Mode 1, OBJ bands, HDMA colour math, BRR samples, SNESMOD music and LoROM/HiROM/ExHiROM images with MSU-1 support.",
      "consoles.snes.item1": "Stage + sprite + collision editors",
      "consoles.snes.item2": "BRR/SFX and SNESMOD soundbanks",
      "consoles.snes.item3": "ROM checksum and SD2SNES readiness",
      "consoles.snes.link": "See SNES output",
      "consoles.md.desc": "SGDK 2.11, H40/H32, 4bpp packed tiles, planes A/B, hardware sprites, XGM2 PCM/FM music, PSG sound and linear mapper profiles with a real SEGA header.",
      "consoles.md.item1": "Native SGDK project generation",
      "consoles.md.item2": "YM2612/PSG VGM and PCM SFX",
      "consoles.md.item3": "Sprite/stage import for 68000",
      "consoles.md.link": "See Mega Drive output",
      "ports.eyebrow": "Source-level ports",
      "ports.title1": "Not a binary translator.",
      "ports.title2": "A second native build.",
      "ports.lede": "A 3.58 MHz 68000 cannot be interpreted by a 65816 in real time, and vice versa. The fork ships per-game adapters that read the original assets and rebuild the game against the target SDK.",
      "ports.gothic.desc": "A complete PVSnesLib homebrew rebuilt for SGDK: original level pages, collision, hero physics, sword combat, three enemy types, title art and music.",
      "ports.sonic.desc": "EHZ Act 1 rebuilt for the 65816: original chunk layout, collision, rings, badniks, springs, monitors, loops, corkscrew, Tails follower and SMPS-derived music.",
      "ports.callout.title": "Cross-platform export is a starting point, not magic.",
      "ports.callout.text": "The editor shows a warning, asks for manual adjustments, and creates the result as",
      "pipeline.eyebrow": "Workflow",
      "pipeline.title1": "From scene to cartridge",
      "pipeline.title2": "in three loops.",
      "pipeline.step1.title": "Import & author",
      "pipeline.step1.desc": "Open a PVSnesLib, WLA-DX or SGDK project, or import a Godot scene. Use the stage, sprite, animation, palette and collision editors to shape the game.",
      "pipeline.step2.title": "Generate & build",
      "pipeline.step2.desc": "Game Build writes a standalone project with converted assets, chooses the ROM profile, runs the real SDK and validates the resulting image.",
      "pipeline.step3.title": "Run & verify",
      "pipeline.step3.desc": "The ROM boots in a real emulator core. Press buttons, step frames, rewind, inspect the audio stream and fix what the preview shows you.",
