      "nav.download": "Tải xuống",
      "hero.eyebrow": "Ngã ba độc lập của Godot 4.7",
      "hero.title1": "Xây dựng cho bảng điều khiển",
      "hero.title2": "điều đó đã nuôi dạy bạn.",
      "hero.lede": "Godot Retro Engine là một nhánh rẽ Godot mã nguồn mở, miễn phí để xây dựng, chuyển và xác thực các trò chơi SNES và Mega Drive. SDK thực, ROM thực, trình mô phỏng thực — với bộ điều hợp cấp nguồn dành cho trò chơi xứng đáng hơn bản dịch nhị phân.",
      "hero.download": "Tải về mới nhất",
      "hero.explore": "Khám phá ngã ba",
      "hero.meta1": "Windows · Linux · macOS",
      "hero.meta2": "Ngã ba được MIT cấp phép",
      "hero.meta3": "Không đo từ xa",
      "stats.consoles": "bảng điều khiển mục tiêu",
      "stats.editors": "biên tập viên cổ điển",
      "stats.builds": "bản dựng máy tính để bàn",
      "stats.source": "quy trình công việc cấp nguồn",
      "features.eyebrow": "Tính năng ngã ba",
      "features.title1": "Một biên tập viên. Hai bảng điều khiển.",
      "features.title2": "Không có hộp đen.",
      "features.lede": "Phân nhánh này duy trì quy trình làm việc của Godot và bổ sung các phần mà một dự án cổ điển thực sự cần: chuỗi công cụ, bộ chuyển đổi nội dung, cấu hình ROM, phản hồi của trình mô phỏng và bộ điều hợp cổng dành riêng cho trò chơi.",
      "feature.build.title": "Xây dựng trò chơi bảng điều khiển kép",
      "feature.build.desc": "Tạo dự án PVSnesLib/SGDK thực và xây dựng ROM có thể chơi được từ cùng một trình chỉnh sửa. Chọn mục tiêu, trình ánh xạ, cấu hình ROM và phần giới thiệu, sau đó xác thực tổng kiểm tra.",
      "feature.ports.title": "Cổng trò chơi cấp nguồn",
      "feature.ports.desc": "Bộ điều hợp chuyên dụng xây dựng lại logic trò chơi cho CPU khác thay vì diễn giải nhị phân 68000 hoặc 65816 trong thời gian thực. Sonic 2 và Gothicvania được đưa ra làm ví dụ hoạt động.",
      "feature.import.title": "Nhập cảnh gốc",
      "feature.import.desc": "Đưa Sprite2D, AnimatedSprite2D, TileMapLayer, va chạm, camera và giao diện người dùng từ cảnh Godot vào diễn viên di động và thời gian chạy sân khấu cho cả hai bảng điều khiển.",
      "feature.editors.title": "Biên tập viên cổ điển",
      "feature.editors.desc": "Trình chỉnh sửa giai đoạn, sprite, hoạt ảnh, bảng màu, va chạm, âm thanh, đầu vào, biểu đồ trạng thái và mã chia sẻ một định dạng dự án và một quy trình xây dựng.",
      "feature.audio.title": "Bàn làm việc âm thanh Console",
      "feature.audio.desc": "MIDI, mô-đun và âm thanh được lấy mẫu trở thành SNESMOD/BRR hoặc YM2612/PSG VGM. SFX có thể được tổng hợp, chuyển đổi và xem trước trước khi chúng được đưa vào ROM.",
      "feature.preview.title": "Trình mô phỏng trong vòng lặp",
      "feature.preview.desc": "Chạy ROM đã xây dựng trong lõi libretro thực, chèn đầu vào pad, chuyển khung hình, tua lại và kiểm tra âm thanh — mà không cần rời khỏi trình chỉnh sửa.",
      "feature.rom.title": "Đường dẫn và xác nhận ROM",
      "feature.rom.desc": "Cấu hình trình ánh xạ LoROM, HiROM, ExHiROM, MSU-1, FastROM và Mega Drive, với tiêu đề, kích thước, tổng kiểm tra và kiểm tra mức độ sẵn sàng của SD2SNES.",
      "feature.fidelity.title": "Trung thực về sự trung thực",
      "consoles.eyebrow": "Mục tiêu",
      "consoles.title1": "Chọn một bảng điều khiển.",
      "consoles.title2": "Người biên tập nói ngôn ngữ của nó.",
      "consoles.snes.desc": "PVSnesLib 4.6, ô 4bpp, Chế độ 1, dải OBJ, toán màu HDMA, mẫu BRR, nhạc SNESMOD và hình ảnh LoROM/HiROM/ExHiROM có hỗ trợ MSU-1.",
      "consoles.snes.item1": "Trình chỉnh sửa giai đoạn + sprite + va chạm",
      "consoles.snes.item2": "Ngân hàng âm thanh BRR/SFX và SNESMOD",
      "consoles.snes.item3": "Tổng kiểm tra ROM và mức độ sẵn sàng của SD2SNES",
      "consoles.snes.link": "Xem đầu ra SNES",
      "consoles.md.desc": "SGDK 2.11, H40/H32, ô đóng gói 4bpp, mặt phẳng A/B, họa tiết phần cứng, nhạc XGM2 PCM/FM, âm thanh PSG và cấu hình trình ánh xạ tuyến tính với tiêu đề SEGA thực.",
      "consoles.md.item1": "Tạo dự án SGDK gốc",
      "consoles.md.item2": "YM2612/PSG VGM và PCM SFX",
      "consoles.md.item3": "Nhập Sprite/giai đoạn cho 68000",
      "consoles.md.link": "Xem đầu ra Mega Drive",
      "ports.eyebrow": "Cổng cấp nguồn",
      "ports.title1": "Không phải là một dịch giả nhị phân.",
      "ports.title2": "Bản dựng gốc thứ hai.",
      "ports.lede": "65816 không thể giải thích được tần số 3,58 MHz 68000 trong thời gian thực và ngược lại. Ngã ba cung cấp các bộ điều hợp cho mỗi trò chơi để đọc nội dung ban đầu và xây dựng lại trò chơi dựa trên SDK mục tiêu.",
      "ports.gothic.desc": "Một homebrew PVSnesLib hoàn chỉnh được xây dựng lại cho SGDK: các trang cấp độ gốc, va chạm, vật lý anh hùng, đấu kiếm, ba loại kẻ thù, nghệ thuật tiêu đề và âm nhạc.",
      "ports.sonic.desc": "EHZ Đạo luật 1 được xây dựng lại cho 65816: bố cục đoạn ban đầu, va chạm, vòng, badniks, lò xo, màn hình, vòng lặp, nút chai, bộ theo dõi Tails và âm nhạc có nguồn gốc từ SMPS.",
      "ports.callout.title": "Xuất khẩu đa nền tảng là điểm khởi đầu, không phải là phép thuật.",
      "ports.callout.text": "Trình chỉnh sửa hiển thị cảnh báo, yêu cầu điều chỉnh thủ công và tạo kết quả dưới dạng",
      "pipeline.eyebrow": "Quy trình làm việc",
      "pipeline.title1": "Từ cảnh đến hộp mực",
      "pipeline.title2": "trong ba vòng.",
      "pipeline.step1.title": "Nhập khẩu & tác giả",
      "pipeline.step1.desc": "Mở dự án PVSnesLib, WLA-DX hoặc SGDK hoặc nhập cảnh Godot. Sử dụng các trình chỉnh sửa sân khấu, sprite, hoạt hình, bảng màu và va chạm để định hình trò chơi.",
      "pipeline.step2.title": "Tạo và xây dựng",
      "pipeline.step2.desc": "Game Build viết một dự án độc lập với nội dung được chuyển đổi, chọn cấu hình ROM, chạy SDK thực và xác thực hình ảnh thu được.",
      "pipeline.step3.title": "Chạy và xác minh",
      "pipeline.step3.desc": "ROM khởi động trong lõi giả lập thực. Nhấn nút, chuyển khung hình, tua lại, kiểm tra luồng âm thanh và sửa những gì bản xem trước hiển thị cho bạn.",
      "showcase.eyebrow": "trưng bày",
      "showcase.title": "ROM thật. Bảng điều khiển thực sự.",
      "showcase.lede": "Mọi hình ảnh bên dưới đều đến từ một ROM được tạo đang chạy trong bản xem trước trình mô phỏng của trình chỉnh sửa.",
      "gallery.ehz": "Sonic 2 · Đồi Ngọc Lục Bảo Phần 1",
      "gallery.gothic_title": "Gothicvania · danh hiệu",
      "gallery.gothic_gameplay": "Gothicvania · lối chơi",
      "gallery.sonic_corkscrew": "Sonic 2 · cái mở nút chai",
      "gallery.gothic_jump": "Gothicvania · nhảy",
      "download.eyebrow": "Tải xuống",
      "download.title1": "Bắt đầu xây dựng",
      "download.title2": "cho phần cứng 16-bit.",
      "download.lede": "Lấy bản dựng trình soạn thảo mới nhất và trỏ nó vào dự án PVSnesLib hoặc SGDK của bạn. Fork là nguồn mở; bản phát hành được xuất bản trên GitHub.",
      "download.button": "Tải xuống trên GitHub",
      "download.tiny": "Bản dựng được gắn thẻ mới nhất: 0.1.60 · Ngã ba Godot 4.7",
      "download.note": "Không có tài khoản, không đo từ xa, không có ROM đi kèm. Mang theo tài sản có được hợp pháp của riêng bạn.",
