      "faq.title1": "Trước bạn",
      "faq.title2": "lắp hộp mực.",
      "faq.lede": "Câu trả lời ngắn gọn cho các câu hỏi mà cổng retro thường đặt ra.",
      "faq.official.q": "Đây có phải là Godot Engine chính thức không?",
      "faq.official.a": "Không. Godot Retro Engine là một nhánh độc lập của Godot 4.7, tập trung vào phát triển SNES và Mega Drive. Nó không được liên kết hoặc xác nhận bởi Godot Foundation.",
      "faq.convert.q": "Nó có thể chuyển đổi bất kỳ trò chơi SNES hoặc Mega Drive nào không?",
      "faq.convert.a": "Không. Dịch nhị phân giữa 65816 và 68000 là không thực tế trong thời gian thực. Fork sử dụng bộ điều hợp cấp nguồn được xây dựng cho mỗi trò chơi; Sonic 2 và Gothicvania là những triển khai tham khảo.",
      "faq.roms.q": "Có bao gồm ROM hoặc tài sản có bản quyền không?",
      "faq.roms.a": "Không. Trình chỉnh sửa và chuỗi công cụ là nguồn mở. Bạn cung cấp dự án nguồn, tài sản và ROM có được một cách hợp pháp của riêng bạn. Các tập tin gốc không bao giờ được sửa đổi bởi nhà xuất khẩu.",
      "faq.apps.q": "Nó có thực sự xây dựng được ứng dụng Windows và macOS không?",
      "faq.apps.a": "Đúng. Linux được xây dựng nguyên bản. Windows được biên dịch chéo với MinGW-w64. macOS được xây dựng với osxcross dưới dạng ứng dụng x86_64 + arm64 phổ biến. Kho lưu trữ phát hành có trên GitHub.",
      "faq.audio.q": "Âm thanh có chính xác không?",
      "faq.audio.a": "Không phải lúc nào cũng vậy. Âm thanh SNES và YM2612 sử dụng các định dạng bảng điều khiển thực và mẫu gốc nếu có nhưng một số đường bao, thời gian và bản ghi âm vẫn ở mức gần đúng.",
      "footer.about": "Một nhánh rẽ Godot độc lập, có sẵn nguồn để phát triển, chuyển và xác thực bảng điều khiển 16-bit.",
