      "faq.lede": "对复古移植通常提出的问题的简短回答。",
      "faq.official.q": "这是官方的 Godot 引擎吗？",
      "faq.official.a": "不。Godot Retro Engine 是 Godot 4.7 的独立分支，专注于 SNES 和 Mega Drive 开发。它不隶属于戈多基金会，也不受其认可。",
      "faq.convert.q": "它可以转换任何 SNES 或 Mega Drive 游戏吗？",
      "faq.convert.a": "不可以。65816 和 68000 之间的二进制转换并不实时实用。该分叉使用每个游戏构建的源级适配器； Sonic 2 和 Gothicvania 是参考实现。",
      "faq.roms.q": "是否包含 ROM 或受版权保护的资产？",
      "faq.roms.a": "不会。编辑器和工具链都是开源的。您提供自己合法获得的源项目、资产和 ROM。原始文件永远不会被出口商修改。",
      "faq.apps.q": "它真的可以构建 Windows 和 macOS 应用程序吗？",
      "faq.apps.a": "是的。 Linux 是原生构建的。 Windows 是与 MinGW-w64 交叉编译的。 macOS 使用 osxcross 作为通用 x86_64 + arm64 应用程序构建。发布档案位于 GitHub 上。",
      "faq.audio.q": "音频位准确吗？",
      "faq.audio.a": "并非总是如此。 SNES 和 YM2612 音频使用真实的控制台格式和可用的原始样本，但某些包络、时序和转录仍然是近似值。",
